alter table public.interest_memberships drop constraint if exists interest_memberships_facet_check;
alter table public.interest_memberships add constraint interest_memberships_facet_check check (facet is null or facet in ('film', 'artwork', 'music', 'distillery', 'listing', 'wildlife', 'tidal', 'silent', 'story', 'planned', 'castle', 'book', 'tradition', 'news'));
delete from public.interest_memberships where category_slug in ('film-art-music','whisky-distilleries','for-sale','unusual-wildlife','tidal-islands','island-castles','island-books','local-traditions','unusual-news');
