insert into public.interest_categories (slug, label, blurb, status, sort_order, populator, acceptance_rules) values ('whisky-distilleries', 'Whisky', 'Working distilleries, silent stills, and the whisky stories that name the island.', 'published', 20, 'wikidata_and_wikipedia', 'The still is on the island. A working distillery, a silent still the source places on the island, a still the source says is not yet producing, or a whisky story (wreck, film, or festival) whose page names the island. Gin, a stalled plan, a brand whose still is elsewhere, and a closed site the page cannot locate are out.') on conflict (slug) do update set label = excluded.label, blurb = excluded.blurb, status = 'published', sort_order = excluded.sort_order, populator = excluded.populator, acceptance_rules = excluded.acceptance_rules;
insert into public.interest_categories (slug, label, blurb, status, sort_order, populator, acceptance_rules) values ('unusual-wildlife', 'Rare wildlife', 'Islands with a rare, endemic, or remarkable animal or plant.', 'published', 25, 'cited_research', 'A Wikipedia, Wikidata, or Open Government Licence page names the species and the island. The species is endemic, named for the island, or a principal stronghold. No colony coordinates, nest counts, or visit advice. The picture is of the species.') on conflict (slug) do update set label = excluded.label, blurb = excluded.blurb, status = 'published', sort_order = excluded.sort_order, populator = excluded.populator, acceptance_rules = excluded.acceptance_rules;
insert into public.interest_categories (slug, label, blurb, status, sort_order, populator, acceptance_rules) values ('tidal-islands', 'Tidal islands', 'Islands joined to other land at low tide and cut off at high tide.', 'published', 35, 'wikipedia_tidal_island', 'The English Wikipedia article Tidal island names the island for Britain, Ireland, Guernsey, or Jersey, and the link is exposed at low tide and submerged at high tide. A permanent causeway named on that page is out. No crossing times.') on conflict (slug) do update set label = excluded.label, blurb = excluded.blurb, status = 'published', sort_order = excluded.sort_order, populator = excluded.populator, acceptance_rules = excluded.acceptance_rules;
insert into public.interest_categories (slug, label, blurb, status, sort_order, populator, acceptance_rules) values ('island-castles', 'Islands with Castles', 'Islands with a castle standing on them.', 'published', 40, 'cited_castle', 'A castle stands on the atlas island. The citation is English Wikipedia, Wikidata, OpenStreetMap, Canmore, the National Heritage List for England, Cadw, or the Archaeological Survey of Ireland. A martello tower, a broch, and a fort do not count. Great Britain and Ireland do not count. No living owner, private address, or way in.') on conflict (slug) do update set label = excluded.label, blurb = excluded.blurb, status = 'published', sort_order = excluded.sort_order, populator = excluded.populator, acceptance_rules = excluded.acceptance_rules;
insert into public.interest_categories (slug, label, blurb, status, sort_order, populator, acceptance_rules) values ('island-books', 'Books', 'Novels, memoirs, and stories set on the island.', 'published', 22, 'cited_book', 'The English Wikipedia article sets the book on the atlas island. Inspired by, based on, and filmed on do not count. Great Britain and Ireland do not count. The picture is an open-licence image of the book, or a photograph of the island when the cover is not open.') on conflict (slug) do update set label = excluded.label, blurb = excluded.blurb, status = 'published', sort_order = excluded.sort_order, populator = excluded.populator, acceptance_rules = excluded.acceptance_rules;
insert into public.interest_categories (slug, label, blurb, status, sort_order, populator, acceptance_rules) values ('local-traditions', 'Local traditions', 'A custom, festival, dance, or craft the source places on the island.', 'published', 24, 'cited_tradition', 'The English Wikipedia article describes the custom and places it on the atlas island. The summary is the article''s own sentences. A legend with no practice, a breed, a book, a film, and a monastic pilgrimage do not count. Great Britain and Ireland do not count. The picture is an open-licence photograph of the custom, or of the island when the article has none.') on conflict (slug) do update set label = excluded.label, blurb = excluded.blurb, status = 'published', sort_order = excluded.sort_order, populator = excluded.populator, acceptance_rules = excluded.acceptance_rules;
insert into public.interest_categories (slug, label, blurb, status, sort_order, populator, acceptance_rules) values ('unusual-news', 'Unusual news', 'Strange events a news report places on the island.', 'published', 18, 'cited_news', 'A news report or published account places the event on that atlas island. The summary is original. The picture is an open-licence photograph of the subject. Great Britain and Ireland do not count. No private address, no photograph of a person, and no grave coordinates.') on conflict (slug) do update set label = excluded.label, blurb = excluded.blurb, status = 'published', sort_order = excluded.sort_order, populator = excluded.populator, acceptance_rules = excluded.acceptance_rules;
