('island-castles', 'osm-relation-12597289', 'castle', 'Balfour Castle', 'https://en.wikipedia.org/wiki/Balfour_Castle', 'Balfour Castle', 'CC BY-SA 4.0', 'Wikipedia places it on this island. Balfour Castle.', 'Q4850755', 'high', 'accepted'),
