('whisky-distilleries', 'mainland-orkney', 'story', 'Illicit still at Highland Park', 'https://en.wikipedia.org/wiki/Highland_Park_distillery', 'Highland Park distillery', 'CC BY-SA 4.0', 'Wikipedia''s Highland Park article places illegal distillation in 1798 on the Kirkwall site in Orkney.', 'Highland_Park_distillery', 'high', 'accepted'),
('whisky-distilleries', 'osm-relation-15708714', 'story', 'Whisky Galore novel', 'https://en.wikipedia.org/wiki/Whisky_Galore_(novel)', 'Whisky Galore (novel)', 'CC BY-SA 4.0', 'Wikipedia''s article on the novel places the wreck it is based on off Eriskay, and Little Todday''s geography on Eriskay.', 'Whisky_Galore_(novel)', 'high', 'accepted'),
